const { ShopifyClientError, normalizeClientError } = require('../errors');
const { requireWithFallback } = require('../require-package');

const {
  getAllProducts,
  getProductsByIds,
  getFullProductDetails,
  getPublicationMap,
  createProduct,
  updateProduct,
  deleteProduct,
  normalizeProductId,
  parseProductIdList
} = requireWithFallback(
  require,
  '../../../../../lib/objects/products',
  '../../../../cli/lib/objects/products'
);

function wrap(operation, fn) {
  return async (...args) => {
    try {
      return await fn(...args);
    } catch (error) {
      throw normalizeClientError(error, `${operation} failed`);
    }
  };
}

function createProductsClient({ store }) {
  if (!store) {
    throw new ShopifyClientError('Products client requires a bound store', {
      code: 'MISSING_STORE'
    });
  }

  return {
    listAll: wrap('Product list', () => getAllProducts(store)),
    listByIds: wrap('Product list by IDs', (ids) => getProductsByIds(store, ids)),
    getFull: wrap('Product fetch', (productId) => getFullProductDetails(store, productId)),
    listPublications: wrap('Publication list', async () => {
      const map = await getPublicationMap(store);
      return Array.from(map.entries()).map(([name, id]) => ({ id, name }));
    }),
    create: wrap('Product create', (productData, context = {}) =>
      createProduct(
        store,
        productData,
        context.destinationCollectionMap || new Map(),
        context.publicationIdMap || new Map()
      )
    ),
    update: wrap('Product update', (productId, productData, context = {}) =>
      updateProduct(
        store,
        productId,
        productData,
        context.destinationCollectionMap || new Map(),
        context.publicationIdMap || new Map()
      )
    ),
    delete: wrap('Product delete', (productId) => deleteProduct(store, productId)),
    normalizeId: normalizeProductId,
    parseIdList: parseProductIdList
  };
}

module.exports = {
  createProductsClient
};
